import pandas as pd
import glob

files = glob.glob('CHIP_DP10_GQ20_PASS/*.xlsx')
false_chip = []
has_intergenic = []
for f in files:
    df = pd.read_excel(f, header=1)
    vc = df['In_CHIP'].value_counts().to_dict()
    if False in vc or 'False' in str(vc):
        false_chip.append((f.split('/')[-1], vc))
    so = df['Sequence Ontology (Combined)'].fillna('').astype(str)
    if so.str.contains('intergenic', case=False).any():
        has_intergenic.append(f.split('/')[-1])

print('Files with non-True In_CHIP values:')
if false_chip:
    for f, vc in false_chip:
        print(f, vc)
else:
    print('None - all files have only True')

print()
print('Files with intergenic variants:')
if has_intergenic:
    for f in has_intergenic:
        print(f)
else:
    print('None')
